package solution

import (
	"bytes"
	"encoding/json"
	"reflect"
	"testing"
)

func TestDeviceConfigConstructionAndToken(t *testing.T) {
	c := NewDeviceConfig("sensor", 4, "private-token")
	if c.Label != "sensor" || c.Level != 4 || c.Token() != "private-token" {
		t.Fatalf("constructed config = %#v, token %q", c, c.Token())
	}
}

func TestEncodeDeviceConfigUsesExactlyPublicKeys(t *testing.T) {
	c := NewDeviceConfig("device <one>", 10, "SECRET-MARKER")
	data, err := EncodeDeviceConfig(c)
	if err != nil {
		t.Fatal(err)
	}
	if bytes.Contains(data, []byte("SECRET-MARKER")) || bytes.Contains(data, []byte("token")) {
		t.Fatalf("private token appeared in JSON: %s", data)
	}

	obj, err := DecodeJSONObject(data)
	if err != nil {
		t.Fatalf("encoded data is not a JSON object: %v", err)
	}
	if len(obj) != 2 || obj["label"] != "device <one>" || obj["level"] != json.Number("10") {
		t.Fatalf("encoded object = %#v", obj)
	}
	if _, ok := obj["token"]; ok {
		t.Fatal("encoded object contains token key")
	}
}

func TestDeviceConfigValidation(t *testing.T) {
	invalid := []DeviceConfig{
		NewDeviceConfig("", 0, "x"),
		NewDeviceConfig(" \t\n", 0, "x"),
		NewDeviceConfig("valid", 11, "x"),
		NewDeviceConfig("valid", 255, "x"),
	}
	for _, c := range invalid {
		if _, err := EncodeDeviceConfig(c); err == nil {
			t.Errorf("invalid config unexpectedly encoded: %#v", c)
		}
	}
	for _, c := range []DeviceConfig{
		NewDeviceConfig("x", 0, "secret"),
		NewDeviceConfig(" x ", 10, "secret"),
	} {
		if _, err := EncodeDeviceConfig(c); err != nil {
			t.Errorf("valid boundary config rejected: %#v: %v", c, err)
		}
	}
}

func TestDecodeDeviceConfig(t *testing.T) {
	input := []byte(" \n{\"label\":\"unit\",\"level\":7}\t")
	before := append([]byte(nil), input...)
	got, err := DecodeDeviceConfig(input)
	if err != nil {
		t.Fatal(err)
	}
	if got.Label != "unit" || got.Level != 7 || got.Token() != "" {
		t.Fatalf("decoded config = %#v, token %q", got, got.Token())
	}
	if !bytes.Equal(input, before) {
		t.Fatal("DecodeDeviceConfig mutated input")
	}

	input[12] = 'X'
	if got.Label != "unit" {
		t.Fatalf("decoded config aliases input: %#v", got)
	}
}

func TestDecodeDeviceConfigRejectsMalformedAndNonExactObjects(t *testing.T) {
	cases := [][]byte{
		nil,
		{},
		[]byte("   "),
		[]byte("null"),
		[]byte("[]"),
		[]byte("{\"label\":\"x\"}"),
		[]byte("{\"level\":1}"),
		[]byte("{\"label\":\"x\",\"level\":1,\"extra\":true}"),
		[]byte("{\"label\":\"x\",\"label\":\"y\",\"level\":1}"),
		[]byte("{\"label\":\"x\",\"level\":1,\"level\":2}"),
		[]byte("{\"label\":1,\"level\":1}"),
		[]byte("{\"label\":null,\"level\":1}"),
		[]byte("{\"label\":\"x\",\"level\":\"1\"}"),
		[]byte("{\"label\":\"x\",\"level\":-1}"),
		[]byte("{\"label\":\"x\",\"level\":11}"),
		[]byte("{\"label\":\"   \",\"level\":1}"),
		[]byte("{\"label\":\"x\",\"level\":1.5}"),
		[]byte("{\"label\":\"x\",\"level\":1} trailing"),
		[]byte("{\"label\":\"x\",\"level\":1}{\"label\":\"y\",\"level\":2}"),
		[]byte("{\"label\":\"x\",\"level\":1"),
	}
	for i, data := range cases {
		before := append([]byte(nil), data...)
		if _, err := DecodeDeviceConfig(data); err == nil {
			t.Errorf("invalid case %d unexpectedly decoded: %q", i, data)
		}
		if !bytes.Equal(data, before) {
			t.Errorf("invalid case %d mutated its input", i)
		}
	}
}

func TestDecodeJSONObjectNumbersNestedValuesAndDuplicateKeys(t *testing.T) {
	data := []byte(`{"n":1.25,"a":[2,{"x":3}],"k":1,"k":4}`)
	before := append([]byte(nil), data...)
	got, err := DecodeJSONObject(data)
	if err != nil {
		t.Fatal(err)
	}
	if got["n"] != json.Number("1.25") || got["k"] != json.Number("4") {
		t.Fatalf("top-level numbers or duplicate handling incorrect: %#v", got)
	}
	array, ok := got["a"].([]interface{})
	if !ok || len(array) != 2 || array[0] != json.Number("2") {
		t.Fatalf("nested array = %#v", got["a"])
	}
	nested, ok := array[1].(map[string]interface{})
	if !ok || nested["x"] != json.Number("3") {
		t.Fatalf("nested object = %#v", array[1])
	}
	if !bytes.Equal(data, before) {
		t.Fatal("DecodeJSONObject mutated input")
	}
}

func TestDecodeJSONObjectAcceptsEmptyObject(t *testing.T) {
	got, err := DecodeJSONObject([]byte(" { } \n"))
	if err != nil {
		t.Fatal(err)
	}
	if got == nil || len(got) != 0 {
		t.Fatalf("empty object decoded as %#v; want non-nil empty map", got)
	}
}

func TestDecodeJSONObjectRejectsNonObjectsAndTrailingData(t *testing.T) {
	cases := [][]byte{
		nil,
		{},
		[]byte("   "),
		[]byte("null"),
		[]byte("[]"),
		[]byte("1"),
		[]byte("true"),
		[]byte(`"text"`),
		[]byte("{"),
		[]byte("{}x"),
		[]byte("{} []"),
	}
	for i, data := range cases {
		if _, err := DecodeJSONObject(data); err == nil {
			t.Errorf("invalid case %d unexpectedly decoded: %q", i, data)
		}
	}
}

func TestDecodeJSONObjectReturnsIndependentValues(t *testing.T) {
	raw := []byte(`{"s":"original","nested":{"v":"inside"},"a":["item"]}`)
	got, err := DecodeJSONObject(raw)
	if err != nil {
		t.Fatal(err)
	}
	copyOfResult := map[string]interface{}{
		"s":      "original",
		"nested": map[string]interface{}{"v": "inside"},
		"a":      []interface{}{"item"},
	}
	for i := range raw {
		raw[i] = 'x'
	}
	if !reflect.DeepEqual(got, copyOfResult) {
		t.Fatalf("decoded result changed after input mutation: %#v", got)
	}
}

package solution

import "testing"

func TestReviewDeviceKeysAreExact(t *testing.T) {
	for _, input := range []string{`{"Label":"x","level":1}`, `{"label":"x","Level":1}`} {
		if got, err := DecodeDeviceConfig([]byte(input)); err == nil {
			t.Errorf("non-exact field spelling accepted: input=%s got=%+v", input, got)
		}
	}
}

